package com.footballacademy.services.scouting;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TalentScoringService { private final PlayerRepository players; private final ScoutingReportRepository reports; private final TalentScoreRepository scores; private final PlayerRankingRepository rankings; public TalentScoringService(PlayerRepository players, ScoutingReportRepository reports, TalentScoreRepository scores, PlayerRankingRepository rankings){this.players=players;this.reports=reports;this.scores=scores;this.rankings=rankings;} @Transactional public TalentScore generateTalentScore(Long playerId){Player p=players.findById(playerId).orElseThrow(); double base=Optional.ofNullable(p.getAverageRating()).orElse(0.0)*10.0; double reportAvg=reports.findByPlayer_Id(playerId).stream().mapToDouble(ScoutingReport::calculateOverallScore).average().orElse(base); TalentScore s=new TalentScore(); s.setPlayer(p); s.setScore(Math.round(((base+reportAvg)/2.0)*100.0)/100.0); s.setConfidence(reports.findByPlayer_Id(playerId).isEmpty()?0.35:0.75); s.setRiskLevel(s.getScore()>=75?"LOW":s.getScore()>=55?"MEDIUM":"HIGH"); return scores.save(s);} public TalentScore recomputeFromReports(Long playerId){return generateTalentScore(playerId);} public List<PlayerRanking> rankPlayers(Long academyId){return rankings.findAll().stream().filter(r->r.getPlayer()!=null&&r.getPlayer().getAcademy()!=null&&academyId.equals(r.getPlayer().getAcademy().getId())).sorted(Comparator.comparing(PlayerRanking::getScore, Comparator.nullsLast(Comparator.reverseOrder()))).toList();} }
